grant create on schema app_private,api to git_tutor_commands;
create table app_private.tutor_unavailability_incidents(id uuid primary key default gen_random_uuid(),tutor_id uuid not null references app_private.tutors(id),from_at timestamptz not null,to_at timestamptz not null,reason text not null,reported_by uuid not null references app_private.accounts(id),version integer not null default 1,created_at timestamptz not null default now(),check(isfinite(from_at) and isfinite(to_at) and to_at>from_at));
create table app_private.unavailability_cases(id uuid primary key default gen_random_uuid(),incident_id uuid not null references app_private.tutor_unavailability_incidents(id),occurrence_id uuid not null references app_private.occurrences(id),owner_account_id uuid not null references app_private.accounts(id),state text not null default 'open' check(state in('open','resolved')),resolution_proposal_id uuid,version integer not null default 1,created_at timestamptz not null default now(),resolved_at timestamptz,unique(incident_id,occurrence_id));
create table app_private.occurrence_series(id uuid primary key default gen_random_uuid(),title text not null,created_by uuid not null references app_private.accounts(id),version integer not null default 1,created_at timestamptz not null default now());
create table app_private.occurrence_series_members(series_id uuid not null references app_private.occurrence_series(id),occurrence_id uuid not null unique references app_private.occurrences(id),created_at timestamptz not null default now(),primary key(series_id,occurrence_id));
create table app_private.series_change_sets(id uuid primary key default gen_random_uuid(),series_id uuid not null references app_private.occurrence_series(id),selection jsonb not null,reason text not null,created_by uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now());
create table app_private.series_change_items(change_set_id uuid not null references app_private.series_change_sets(id),occurrence_id uuid not null references app_private.occurrences(id),proposal_id uuid not null unique references app_private.operation_proposals(id),base_version integer not null,created_at timestamptz not null default now(),primary key(change_set_id,occurrence_id));
do $$declare n text;begin foreach n in array array['tutor_unavailability_incidents','unavailability_cases','occurrence_series','occurrence_series_members','series_change_sets','series_change_items'] loop execute format('alter table app_private.%I enable row level security',n);execute format('grant select,insert on app_private.%I to git_tutor_commands',n);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',n);execute format('create policy teaching_commands on app_private.%I to git_tutor_commands using(true) with check(true)',n);if n<>'unavailability_cases' then execute format('create trigger immutable_teaching_history before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',n);end if;end loop;end $$;
grant update on app_private.unavailability_cases to git_tutor_commands;

create function app_private.teaching_tutor_unavailable(p_tutor uuid,p_start timestamptz,p_end timestamptz) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from app_private.tutor_unavailability_incidents where tutor_id=p_tutor and tstzrange(from_at,to_at,'[)')&&tstzrange(p_start,p_end,'[)'))$$;
create function app_private.teaching_admission_guard() returns trigger language plpgsql security definer set search_path='' as $$declare o app_private.occurrences%rowtype;begin
 if tg_table_name='tutor_reservations' then if new.active and app_private.teaching_tutor_unavailable(new.tutor_id,new.start_at,new.end_at) then raise exception 'SCHEDULE_CONFLICT';end if;
 else select * into o from app_private.occurrences where id=new.occurrence_id;if app_private.teaching_tutor_unavailable(o.tutor_id,o.start_at,o.end_at) then raise exception 'SCHEDULE_CONFLICT';end if;end if;return new;
end $$;
create trigger teaching_admission before insert on app_private.enrollments for each row execute function app_private.teaching_admission_guard();
create trigger teaching_queue_admission before insert on app_private.waitlist_entries for each row execute function app_private.teaching_admission_guard();
create trigger teaching_schedule_admission before insert or update of tutor_id,start_at,end_at,active on app_private.tutor_reservations for each row execute function app_private.teaching_admission_guard();
create or replace function app_private.booking_assert_schedule(p_tutor_id uuid,p_start_at timestamptz,p_end_at timestamptz,p_excluded_occurrence_id uuid default null) returns integer language plpgsql security definer set search_path='' as $$declare rules app_private.availability_rules%rowtype;exceptions jsonb;begin
 perform app_private.booking_validate_times(p_start_at,p_end_at);if app_private.teaching_tutor_unavailable(p_tutor_id,p_start_at,p_end_at) then raise exception 'SCHEDULE_CONFLICT';end if;
 select * into rules from app_private.availability_rules where tutor_id=p_tutor_id;select coalesce(jsonb_agg(jsonb_build_object('local_date',local_date,'intervals',intervals)),'[]') into exceptions from app_private.availability_exceptions where tutor_id=p_tutor_id;
 if rules.id is null or not app_private.booking_schedule_covered(rules.weekly_intervals,exceptions,p_start_at,p_end_at) or exists(select 1 from app_private.tutor_reservations where tutor_id=p_tutor_id and active and(p_excluded_occurrence_id is null or occurrence_id<>p_excluded_occurrence_id) and tstzrange(start_at,end_at,'[)')&&tstzrange(p_start_at,p_end_at,'[)')) then raise exception 'SCHEDULE_CONFLICT';end if;return rules.version;
end $$;
create or replace function app_private.booking_waitlist_eligible(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from app_private.waitlist_entries w join app_private.occurrences o on o.id=w.occurrence_id where w.id=p_id and w.state='waiting' and not app_private.teaching_tutor_unavailable(o.tutor_id,o.start_at,o.end_at) and app_private.booking_can_access(w.requested_by,w.learner_id) and app_private.payment_verified_account(w.requested_by) and not exists(select 1 from app_private.enrollments e where e.occurrence_id=w.occurrence_id and e.learner_id=w.learner_id and(e.state='confirmed' or(e.state='held' and e.hold_expires_at>now()))))$$;
create function app_private.teaching_lock_occurrences(p_occurrence_ids uuid[],p_extra_tutors uuid[] default '{}') returns void language plpgsql security definer set search_path='' as $$declare scope jsonb;begin
 scope:=app_private.booking_financial_scope(array(select id from app_private.enrollments where occurrence_id=any(p_occurrence_ids)));
 scope:=jsonb_set(scope,'{occurrence_ids}',(select coalesce(jsonb_agg(id order by id),'[]') from(select value::uuid id from jsonb_array_elements_text(scope->'occurrence_ids') union select unnest(p_occurrence_ids))x));
 scope:=jsonb_set(scope,'{tutor_ids}',(select coalesce(jsonb_agg(id order by id),'[]') from(select value::uuid id from jsonb_array_elements_text(scope->'tutor_ids') union select tutor_id from app_private.occurrences where id=any(p_occurrence_ids) union select unnest(p_extra_tutors))x));perform app_private.booking_lock_financial_scope(scope);
end $$;
create function app_private.teaching_case_resolution(p_case uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare c app_private.unavailability_cases%rowtype;i app_private.tutor_unavailability_incidents%rowtype;o app_private.occurrences%rowtype;proposal uuid;begin
 select * into c from app_private.unavailability_cases where id=p_case;select * into i from app_private.tutor_unavailability_incidents where id=c.incident_id;select * into o from app_private.occurrences where id=c.occurrence_id;
 if c.state='resolved' then return jsonb_build_object('eligible',false,'proposal_id',c.resolution_proposal_id);end if;
 if o.state in('cancelled','completed') or o.tutor_id<>i.tutor_id or not(tstzrange(o.start_at,o.end_at,'[)')&&tstzrange(i.from_at,i.to_at,'[)')) then select id into proposal from app_private.operation_proposals where occurrence_id=o.id and target_type='occurrence' and state='committed' and committed_at>=i.created_at order by committed_at desc,id desc limit 1;
 return jsonb_build_object('eligible',o.state='cancelled' or proposal is not null,'proposal_id',proposal);end if;return jsonb_build_object('eligible',false,'proposal_id',null);
end $$;
create function app_private.teaching_case_dto(p_case uuid,p_actor uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare c app_private.unavailability_cases%rowtype;o app_private.occurrences%rowtype;tid uuid;resolution jsonb;name text;admin boolean:=app_private.has_role(p_actor,'admin');begin
 select * into c from app_private.unavailability_cases where id=p_case;select tutor_id into tid from app_private.tutor_unavailability_incidents where id=c.incident_id;select * into o from app_private.occurrences where id=c.occurrence_id;resolution:=app_private.teaching_case_resolution(c.id);select p.display_name into name from app_private.accounts a join app_private.people p on p.id=a.person_id where a.id=c.owner_account_id;
 return jsonb_build_object('case_id',c.id,'incident_id',c.incident_id,'occurrence_id',o.id,'tutor_id',tid,'start_at',o.start_at,'end_at',o.end_at,'owner',jsonb_build_object('account_id',c.owner_account_id,'display_name',coalesce(name,'Operations owner')),'status',c.state,'version',c.version,'can_assign',admin and c.state='open','can_resolve',(admin or(c.owner_account_id=p_actor and app_private.has_role(p_actor,'customer_service'))) and (resolution->>'eligible')::boolean,'resolution_proposal_id',resolution->'proposal_id');
end $$;
create function app_private.teaching_operations_command(p_name text,p_input jsonb,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare actor uuid:=app_private.require_actor();ctx jsonb;teacher app_private.tutors%rowtype;rules app_private.availability_rules%rowtype;c app_private.unavailability_cases%rowtype;owner uuid;resource uuid:=gen_random_uuid();count_affected integer;result jsonb;resolution jsonb;ids uuid[];selected uuid[];item jsonb;proposal jsonb;proposals jsonb:='[]';o app_private.occurrences%rowtype;from_at timestamptz;to_at timestamptz;expires timestamptz;begin
 if p_name='report_tutor_unavailability' then select * into teacher from app_private.tutors where id=(p_input->>'tutor_id')::uuid;if teacher.id is null then raise exception 'NOT_FOUND';end if;if teacher.account_id=actor then perform app_private.require_role(actor,'tutor');else perform app_private.require_role(actor,'admin');end if;
 elsif p_name='resolve_unavailability_case' then select * into c from app_private.unavailability_cases where id=(p_input->>'case_id')::uuid;if c.id is null then raise exception 'NOT_FOUND';end if;if not app_private.has_role(actor,'admin') then perform app_private.require_role(actor,'customer_service');if c.owner_account_id<>actor then raise exception 'FORBIDDEN';end if;end if;
 else perform app_private.require_role(actor,'admin');end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_name='report_tutor_unavailability' then
  from_at:=(p_input->>'from_at')::timestamptz;to_at:=(p_input->>'to_at')::timestamptz;perform app_private.booking_validate_times(from_at,to_at);if to_at<=now() or to_at-from_at>interval '366 days' or length(btrim(p_input->>'reason')) not between 1 and 2000 or p_input->>'reason' is null then raise exception 'VALIDATION_ERROR';end if;
  perform 1 from app_private.tutors where id=teacher.id for update;select * into rules from app_private.availability_rules where tutor_id=teacher.id for update;if(p_input->>'expected_version')::integer is distinct from coalesce(rules.version,0) then raise exception 'VERSION_CONFLICT';end if;
  select a.id into owner from app_private.accounts a where app_private.has_role(a.id,'admin') and app_private.payment_verified_account(a.id) order by (a.id=actor) desc,a.id limit 1;if owner is null then raise exception 'STATE_CONFLICT';end if;perform app_private.require_role(owner,'admin');
  if rules.id is null then insert into app_private.availability_rules(tutor_id,weekly_intervals,version) values(teacher.id,'[]',1);else update app_private.availability_rules set version=version+1 where id=rules.id;end if;
  perform 1 from app_private.occurrences where tutor_id=teacher.id and start_at>now() and state in('draft','forming','confirmed') and tstzrange(start_at,end_at,'[)')&&tstzrange(from_at,to_at,'[)') order by id for update;
  insert into app_private.tutor_unavailability_incidents(id,tutor_id,from_at,to_at,reason,reported_by) values(resource,teacher.id,from_at,to_at,p_input->>'reason',actor);
  insert into app_private.unavailability_cases(incident_id,occurrence_id,owner_account_id) select resource,id,owner from app_private.occurrences where tutor_id=teacher.id and start_at>now() and state in('draft','forming','confirmed') and tstzrange(start_at,end_at,'[)')&&tstzrange(from_at,to_at,'[)');get diagnostics count_affected=row_count;
  for o in select x.* from app_private.occurrences x join app_private.unavailability_cases y on y.occurrence_id=x.id where y.incident_id=resource loop perform app_private.enqueue_event(gen_random_uuid(),'tutor_unavailable',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'incident_id',resource,'owner_account_id',owner),'notifications.route');end loop;
  result:=app_private.booking_finish(ctx,resource,1,jsonb_build_object('incident_id',resource,'affected_count',count_affected),'tutor_unavailability_recorded',jsonb_build_object('incident_id',resource));perform set_config('response.status','201',true);return result;
 elsif p_name in('assign_unavailability_case','resolve_unavailability_case') then
  select * into c from app_private.unavailability_cases where id=(p_input->>'case_id')::uuid for update;if c.id is null then raise exception 'NOT_FOUND';end if;if p_name='resolve_unavailability_case' and not app_private.has_role(actor,'admin') and c.owner_account_id<>actor then raise exception 'FORBIDDEN';end if;if(p_input->>'expected_version')::integer is distinct from c.version then raise exception 'VERSION_CONFLICT';end if;if c.state<>'open' then raise exception 'STATE_CONFLICT';end if;
  if p_name='assign_unavailability_case' then owner:=(p_input->>'owner_account_id')::uuid;if owner is null or not app_private.payment_verified_account(owner) or not(app_private.has_role(owner,'admin') or app_private.has_role(owner,'customer_service')) then raise exception 'FORBIDDEN';end if;perform app_private.require_role(owner,case when app_private.has_role(owner,'admin') then 'admin' else 'customer_service' end);update app_private.unavailability_cases set owner_account_id=owner,version=version+1 where id=c.id;result:=jsonb_build_object('owner_account_id',owner);
  else resolution:=app_private.teaching_case_resolution(c.id);if not(resolution->>'eligible')::boolean or(resolution->>'proposal_id')::uuid is distinct from(p_input->>'resolution_proposal_id')::uuid then raise exception 'STATE_CONFLICT';end if;if p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;update app_private.unavailability_cases set state='resolved',resolution_proposal_id=(resolution->>'proposal_id')::uuid,resolved_at=now(),version=version+1 where id=c.id;result:=jsonb_build_object('status','resolved');end if;
  return app_private.booking_finish(ctx,c.id,c.version+1,result,p_name,jsonb_build_object('occurrence_id',c.occurrence_id,'case_id',c.id));
 elsif p_name='create_occurrence_series' then
  if jsonb_typeof(p_input->'occurrence_ids') is distinct from 'array' or jsonb_array_length(p_input->'occurrence_ids') not between 1 and 100 or p_input->>'title' is null or length(btrim(p_input->>'title')) not between 1 and 120 then raise exception 'VALIDATION_ERROR';end if;ids:=array(select value::uuid from jsonb_array_elements_text(p_input->'occurrence_ids'));
  if cardinality(ids)<>(select count(distinct x) from unnest(ids)x) then raise exception 'VALIDATION_ERROR';end if;perform app_private.teaching_lock_occurrences(ids);
  if(select count(*) from app_private.occurrences where id=any(ids) and start_at>now() and state in('forming','confirmed'))<>cardinality(ids) or(select count(distinct offer_id) from app_private.occurrences where id=any(ids))<>1 or exists(select 1 from app_private.occurrence_series_members where occurrence_id=any(ids)) then raise exception 'STATE_CONFLICT';end if;
  insert into app_private.occurrence_series(id,title,created_by) values(resource,btrim(p_input->>'title'),actor);insert into app_private.occurrence_series_members(series_id,occurrence_id) select resource,unnest(ids);result:=app_private.booking_finish(ctx,resource,1,jsonb_build_object('series_id',resource),'occurrence_series_created',jsonb_build_object('series_id',resource));perform set_config('response.status','201',true);return result;
 elsif p_name='create_series_change_set' then
  if not exists(select 1 from app_private.occurrence_series where id=(p_input->>'series_id')::uuid) then raise exception 'NOT_FOUND';end if;
  if jsonb_typeof(p_input->'selection') is distinct from 'object' or(p_input->'selection')-array['mode','occurrence_ids','from_at']<>'{}'::jsonb or jsonb_typeof(p_input->'changes') is distinct from 'array' or jsonb_array_length(p_input->'changes') not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
  expires:=(p_input->>'expires_at')::timestamptz;if expires is null or not isfinite(expires) or expires<=now() or p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  if p_input->'selection'->>'mode'='selected' then if jsonb_typeof(p_input->'selection'->'occurrence_ids') is distinct from 'array' or jsonb_array_length(p_input->'selection'->'occurrence_ids') not between 1 and 100 or p_input->'selection'?'from_at' then raise exception 'VALIDATION_ERROR';end if;selected:=array(select value::uuid from jsonb_array_elements_text(p_input->'selection'->'occurrence_ids') order by value::uuid);
  elsif p_input->'selection'->>'mode'='from' then if p_input->'selection'?'occurrence_ids' or p_input->'selection'->>'from_at' is null then raise exception 'VALIDATION_ERROR';end if;selected:=array(select o.id from app_private.occurrences o join app_private.occurrence_series_members m on m.occurrence_id=o.id where m.series_id=(p_input->>'series_id')::uuid and o.start_at>now() and o.start_at>=(p_input->'selection'->>'from_at')::timestamptz and o.state in('forming','confirmed') order by o.id);
  else raise exception 'VALIDATION_ERROR';end if;
  ids:=array(select(value->>'occurrence_id')::uuid from jsonb_array_elements(p_input->'changes') order by(value->>'occurrence_id')::uuid);
  if cardinality(selected) not between 1 and 100 or cardinality(selected)<>(select count(distinct x) from unnest(selected)x) or selected is distinct from ids then raise exception 'VALIDATION_ERROR';end if;perform app_private.teaching_lock_occurrences(ids);
  if(select count(*) from app_private.occurrence_series_members where series_id=(p_input->>'series_id')::uuid and occurrence_id=any(ids))<>cardinality(ids) or exists(select 1 from app_private.occurrences where id=any(ids) and(state not in('forming','confirmed') or start_at<=now())) then raise exception 'STATE_CONFLICT';end if;
  insert into app_private.series_change_sets(id,series_id,selection,reason,created_by,command_id) values(resource,(p_input->>'series_id')::uuid,p_input->'selection',p_input->>'reason',actor,(ctx->>'command_id')::uuid);
  for item in select value from jsonb_array_elements(p_input->'changes') order by(value->>'occurrence_id')::uuid loop
   if jsonb_typeof(item) is distinct from 'object' or item-array['occurrence_id','expected_version','start_at','end_at']<>'{}'::jsonb or item->>'expected_version' is null or item->>'start_at' is null or item->>'end_at' is null then raise exception 'VALIDATION_ERROR';end if;
   proposal:=api.create_operation_proposal('reschedule',(item->>'occurrence_id')::uuid,jsonb_build_object('target_type','occurrence','start_at',item->>'start_at','end_at',item->>'end_at','time_zone','Africa/Cairo','expires_at',expires),p_input->>'reason',(item->>'expected_version')::integer,'series:'||(ctx->>'command_id')||':'||(item->>'occurrence_id'));
   insert into app_private.series_change_items(change_set_id,occurrence_id,proposal_id,base_version) values(resource,(item->>'occurrence_id')::uuid,(proposal->>'proposal_id')::uuid,(item->>'expected_version')::integer);proposals:=proposals||jsonb_build_array(proposal->'proposal_id');end loop;
  result:=app_private.booking_finish(ctx,resource,1,jsonb_build_object('change_set_id',resource,'proposal_ids',proposals),'series_change_set_created',jsonb_build_object('change_set_id',resource));perform set_config('response.status','201',true);return result;
 else raise exception 'VALIDATION_ERROR';end if;
exception when invalid_text_representation or datetime_field_overflow then raise exception 'VALIDATION_ERROR';
end $$;
create function api.report_tutor_unavailability(p_tutor_id uuid,p_from_at timestamptz,p_to_at timestamptz,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_operations_command('report_tutor_unavailability',jsonb_build_object('tutor_id',p_tutor_id,'from_at',p_from_at,'to_at',p_to_at,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.assign_unavailability_case(p_case_id uuid,p_owner_account_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_operations_command('assign_unavailability_case',jsonb_build_object('case_id',p_case_id,'owner_account_id',p_owner_account_id,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.resolve_unavailability_case(p_case_id uuid,p_resolution_proposal_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_operations_command('resolve_unavailability_case',jsonb_build_object('case_id',p_case_id,'resolution_proposal_id',p_resolution_proposal_id,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.create_occurrence_series(p_title text,p_occurrence_ids uuid[],p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_operations_command('create_occurrence_series',jsonb_build_object('title',p_title,'occurrence_ids',p_occurrence_ids),p_idempotency_key)$$;
create function api.create_series_change_set(p_series_id uuid,p_selection jsonb,p_changes jsonb,p_expires_at timestamptz,p_reason text,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_operations_command('create_series_change_set',jsonb_build_object('series_id',p_series_id,'selection',p_selection,'changes',p_changes,'expires_at',p_expires_at,'reason',p_reason),p_idempotency_key)$$;

create function api.list_unavailability_cases(p_tutor_id uuid default null,p_state text default null,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();admin boolean;teacher uuid;after_at timestamptz;after_id uuid;rows jsonb;begin
 admin:=app_private.has_role(actor,'admin');if not admin and not app_private.has_role(actor,'customer_service') then perform app_private.require_role(actor,'tutor');select id into teacher from app_private.tutors where account_id=actor;if p_tutor_id is not null and p_tutor_id<>teacher then raise exception 'FORBIDDEN';end if;end if;
 if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('open','resolved')) then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.teaching_case_dto(x.id,actor)) order by x.created_at desc,x.id desc),'[]') into rows from(select c.* from app_private.unavailability_cases c join app_private.tutor_unavailability_incidents i on i.id=c.incident_id where(admin or i.tutor_id=teacher or(c.owner_account_id=actor and app_private.has_role(actor,'customer_service'))) and(p_tutor_id is null or i.tutor_id=p_tutor_id) and(p_state is null or c.state=p_state) and(p_cursor is null or(c.created_at,c.id)<(after_at,after_id)) order by c.created_at desc,c.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end $$;
create function app_private.teaching_series_read(p_kind text,p_id uuid,p_tutor_id uuid,p_cursor text,p_limit integer) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();admin boolean:=app_private.has_role(actor,'admin');teacher uuid;after_at timestamptz;after_id uuid;rows jsonb;result jsonb;series app_private.occurrence_series%rowtype;changes app_private.series_change_sets%rowtype;state text;begin
 if not admin then perform app_private.require_role(actor,'tutor');select id into teacher from app_private.tutors where account_id=actor;if p_tutor_id is not null and p_tutor_id<>teacher then raise exception 'FORBIDDEN';end if;end if;
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 if p_kind='list' then select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('series_id',x.id,'title',x.title,'version',x.version,'created_at',x.created_at)) order by x.created_at desc,x.id desc),'[]') into rows from(select s.* from app_private.occurrence_series s where exists(select 1 from app_private.occurrence_series_members m join app_private.occurrences o on o.id=m.occurrence_id where m.series_id=s.id and(admin or o.tutor_id=teacher) and(p_tutor_id is null or o.tutor_id=p_tutor_id)) and(p_cursor is null or(s.created_at,s.id)<(after_at,after_id)) order by s.created_at desc,s.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end if;
 if p_kind='changes' then select * into changes from app_private.series_change_sets where id=p_id;p_id:=changes.series_id;end if;select * into series from app_private.occurrence_series where id=p_id;
 if series.id is null or not exists(select 1 from app_private.occurrence_series_members m join app_private.occurrences o on o.id=m.occurrence_id where m.series_id=series.id and(admin or o.tutor_id=teacher)) then raise exception 'NOT_FOUND';end if;
 if p_kind='detail' then
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.start_at,'data',jsonb_build_object('occurrence_id',x.id,'tutor_id',x.tutor_id,'version',x.version,'start_at',x.start_at,'end_at',x.end_at,'state',x.state)) order by x.start_at desc,x.id desc),'[]') into rows from(select o.* from app_private.occurrences o join app_private.occurrence_series_members m on m.occurrence_id=o.id where m.series_id=series.id and(admin or o.tutor_id=teacher) and(p_cursor is null or(o.start_at,o.id)<(after_at,after_id)) order by o.start_at desc,o.id desc limit p_limit+1)x;
 return app_private.package_page(rows,p_limit)||jsonb_build_object('series_id',series.id,'title',series.title,'version',series.version);
 elsif p_kind='changes' then
 select case when bool_and(p.state='committed') then 'committed' when bool_or(p.state='committed') then 'partially_committed' when bool_and(p.state in('declined','expired')) then 'closed' else 'proposed' end into state from app_private.series_change_items i join app_private.operation_proposals p on p.id=i.proposal_id where i.change_set_id=changes.id;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.occurrence_id,'at',x.created_at,'data',jsonb_build_object('occurrence_id',x.occurrence_id,'proposal_id',x.proposal_id,'base_version',x.base_version,'state',x.state)) order by x.created_at desc,x.occurrence_id desc),'[]') into rows from(select i.*,p.state from app_private.series_change_items i join app_private.operation_proposals p on p.id=i.proposal_id join app_private.occurrences o on o.id=i.occurrence_id where i.change_set_id=changes.id and(admin or o.tutor_id=teacher) and(p_cursor is null or(i.created_at,i.occurrence_id)<(after_at,after_id)) order by i.created_at desc,i.occurrence_id desc limit p_limit+1)x;
 result:=app_private.package_page(rows,p_limit);return result||jsonb_build_object('change_set_id',changes.id,'series_id',series.id,'state',state);
 else raise exception 'VALIDATION_ERROR';end if;
end $$;
create function api.list_occurrence_series(p_tutor_id uuid default null,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_series_read('list',null,p_tutor_id,p_cursor,p_limit)$$;
create function api.get_occurrence_series(p_series_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_series_read('detail',p_series_id,null,p_cursor,p_limit)$$;
create function api.get_series_change_set(p_change_set_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.teaching_series_read('changes',p_change_set_id,null,p_cursor,p_limit)$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('teaching_tutor_unavailable','teaching_admission_guard','teaching_lock_occurrences','teaching_case_resolution','teaching_case_dto','teaching_operations_command','teaching_series_read'))or(n.nspname='api' and p.proname in('report_tutor_unavailability','assign_unavailability_case','resolve_unavailability_case','create_occurrence_series','create_series_change_set','list_unavailability_cases','list_occurrence_series','get_occurrence_series','get_series_change_set')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema app_private,api from git_tutor_commands;
notify pgrst,'reload schema';
